@props([ 'name' => null, 'id' => null, 'value' => null, 'label' => null, 'checked' => false, 'disabled' => false, ]) @php $radioId = $id ?: ($name ? $name . '-' . $value : 'ui-rad-' . uniqid()); $isChecked = (bool)($checked || ($name && old($name) == $value)); @endphp <label class="ui-check-label" for="{{ $radioId }}"><input type="radio" class="ui-radio" id="{{ $radioId }}" @if($name) name="{{ $name }}" @endif value="{{ $value }}" @if($isChecked) checked @endif @if($disabled) disabled @endif {{ $attributes }} /> @if($label || $slot->isNotEmpty() ) <span>{{ $label ?? $slot }}</span> @endif </label>